/* Explosion debris: 20 bursts thrown out along dir with random spread, each trailing 10 smoke puffs. */
void spawn_amoeboid_hit_sparks(void *m, void *dir) {
    float p[4];
    float v[4];
    float a[4];
    char *pos = (char *)m + 0x10;
    int i, j;
    for (i = 0; i < 20; i++) {
        float ang, sp, up;
        qcopy(p, pos);
        add_random_offset_to_vector_xyz(p, 0.25f);
        p[2] += 1.0f;
        ang = random_angle_radians();
        sp = random_float_between(1.0f, 8.0f);
        up = random_float_between(2.0f, 6.0f);
        FastVecScale(v, dir, random_float_between(0.0f, 1.0f));
        v[0] += FastCos(ang) * (sp * g_frame_time);
        v[1] += FastSin(ang) * (sp * g_frame_time);
        v[2] += up * g_frame_time;
        qcopy(a, v);
        a[2] -= g_frame_time_sq * 20.0f * (float)scale_ticks(0x1E);
        for (j = 0; j < 10; j++) {
            float r = random_float_between(0.5f, 1.5f);
            int c1, c2, n1, n2;
            v[3] = r * 0.125f;
            a[3] = r * 0.065f;
            add_random_offset_to_vector_xyz(p, 0.2f);
            add_random_offset_to_vector_xyz(a, g_frame_time * 0.5f);
            c1 = FastTweenColor(0x8000EEEE, 0x8000FF90, random_float_between(0.0f, 1.0f));
            c2 = FastTweenColor(0xFFEE, 0xFFEE, random_float_between(0.0f, 1.0f));
            n1 = scale_ticks(10);
            n2 = scale_ticks(0x1E);
            PartType02Spawn(p, v, a, c1, c2, n1, n2, truncate_float_to_s32_r(multiply_global_factor(random_float_between(5.0f, 25.0f))), -1);
        }
    }
}
